def _split_at_impl(iterable, pred, keep_separator=False, maxsplit=None):
    it = iter(iterable)
    buf = []
    splits = 0

    for item in it:
        if pred(item):
            # Check if we've already reached maxsplit
            if maxsplit is not None and splits >= maxsplit:
                # No more splits - include this item and rest in final chunk
                if keep_separator:
                    buf.append(item)
                else:
                    # Include current item and all remaining items
                    buf.extend([item])
                    for remaining_item in it:
                        buf.append(remaining_item)
                    yield buf
                    return
            else:
                if keep_separator:
                    buf.append(item)
                yield buf
                buf = []
                splits += 1
        else:
            buf.append(item)

    yield buf

